return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n > 1;','language'=>'fr','project-id-version'=>'Plugins - PublishPress Permissions: Control User Access for Posts, Pages, Categories, Tags - Stable (latest release)','pot-creation-date'=>'2026-05-26T19:56:47+00:00','po-revision-date'=>'2026-05-27 10:17+0200','x-generator'=>'Poedit 3.7','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions vous permet d’autoriser ou de refuser l’accès aux articles, aux pages, aux catégories, aux balises et bien plus encore.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'Modifier l’étiquette pour tous les types de publication','Edit Tag for Posts'=>'Modifier l’étiquette pour tous les publications','Advanced Custom Fields'=>'Advanced Custom Fields','Control front-end access to Field Groups with advanced permission management.'=>'Contrôler l’accès par l’interface publique aux groupes de champs grâce à une gestion avancée des droits.','Control access to Field Groups'=>'Contrôler l’accès aux groupes de champs','Front-end visibility restrictions'=>'Restrictions de visibilité de l’interface publique','Integration with permission groups'=>'Intégration avec les groupes de droits','Beaver Builder'=>'Beaver Builder','Compatibility with Edit Permissions in Beaver Builder.'=>'Compatibilité avec les droits de modification dans Beaver Builder.','Beaver editor integration'=>'Intégration avec l’éditeur de Beaver','Widget-level permission controls'=>'Contrôles des droits au niveau des widgets','Template access restrictions'=>'Restrictions d’accès aux modèles','bbPress Forums'=>'Forums bbPress','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'Droits spécifiques au forum de bbPress avec contrôl détaillé sur l’accès et la partecipation au forum.','Forum-specific permissions'=>'Droits spécifiques au forum','Topic creation restrictions'=>'Restrictions à la création de sujets','Forum access controls'=>'Contrôles d’accès au forum','BuddyPress'=>'BuddyPress','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'Assigner des droits de publication et de terme aux groupes BuddyPress pour un contrôle amélioré du contenu.','Assign post permissions to BuddyPress groups'=>'Assigner des droits de publication aux groupes BuddyPress','Assign term permissions to BuddyPress groups'=>'Assigner des droits de terme aux groupes BuddyPress','Group-based content permissions'=>'Droits de contenu basés sur les groupes','CMS Tree View'=>'CMS Tree View','Compatibility with Edit Permissions in CMS Tree View.'=>'Compatibilité avec les droits de modification dans CMS Tree View.','Permission-aware tree view'=>'Vue en arborescence sensible aux droits','Hierarchical content controls'=>'Contrôles du contenu hiérarchiques','Elementor'=>'Elementor','Compatibility with Edit Permissions in Elementor.'=>'Compatibilité avec les droits de modification dans Elementor.','Elementor editor integration'=>'Intégration avec l’éditeur de Elementor','The Events Calendar'=>'The Events Calendar','Apply permission controls to events and event-related content.'=>'Appliquer des contrôles des droits aux événements et aux contenus liés aux événements.','Event post permissions'=>'Droits de publication d’événements','Event taxonomy controls'=>'Contrôles de la taxonomie des événements','Nested Pages'=>'Nested Pages','Compatibility with Edit Permissions in Nested Pages.'=>'Compatibilité avec les droits de modification dans Nested Pages.','Permission-aware nested view'=>'Vue imbriquée sensible aux droits','Quick edit integration'=>'Intégration avec la modification rapide','PublishPress Statuses'=>'PublishPress Statuses','Compatibility with PublishPress Statuses plugin.'=>'Compatibilité avec l’extension PublishPress Statuses.','Custom status permissions'=>'Droits d’état personnalisés','Workflow-specific access controls'=>'Contrôles des droits spécifique pour le flux de travail','Status-based editing capabilities'=>'Permissions de modification basés sur l’état','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'Filtrer les résultats de recherche en fonction des droits d’affichage pour une découverte sécurisée du contenu.','Search result filtering'=>'Filtrage des résultats de recherche','Permission-aware indexing'=>'Indexation sensible aux droits','Secure content discovery'=>'Découverte sécurisée de contenu','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'Compatibilité avec le filtrage des termes de SearchWP pour les permissions de recherche avancées.','Permission-aware search results'=>'Résultats de recherche sensible aux droits','Term-based filtering'=>'Filtrage basé sur le terme','Advanced search controls'=>'Contrôles de recherche avancée','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'Appliquer des contrôles des droits aux produits et catégories de produits de WooCommerce.','Product permissions'=>'Droits de produit','Product category controls'=>'Contrôles de catégorie de produit','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'Prise en charge multilingue avec synchronisation des droits d’accès pour toutes les traductions de contenu.','Permission synchronization across translations'=>'Synchronisation des droits entre les différentes traductions','Language-specific content access'=>'Accès au contenu spécifique à une langue','Multilingual permission management'=>'Gestion multilingue des droits','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'Exclure les publications restreintes des sitemaps XML afin de maintenir un référencement SEO correct.','Sitemap filtering for restricted content'=>'Filtrage du plan du site pour les contenus restreints','Search engine visibility controls'=>'Contrôles de visibilité dans les moteurs de recherche','Permission-aware XML sitemaps'=>'Sitemaps XML sensibles aux droits','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'Compatibilité avec le constructeur YooTheme et les droits de termes.','Builder interface compatibility'=>'Compatibilité avec l’interface du constructeur','Term permission integration'=>'Intégration des droits des termes','Template access controls'=>'Contrôles d’accès aux modèles','Viewing'=>'Visualisation','Access Circles'=>'Accès aux cercles','Editing Permissions'=>'Modifications des droits','Compatibility Pack'=>'Compatibility Pack','Teaser'=>'Présentation','File Access'=>'Accès aux fichiers','Membership'=>'Adhésion','User Posts'=>'Publications des utilisateurs/utilisatrices','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'Les cercles de visibilité et les cercles éditoriaux bloquent l’accès aux contenus qui ne sont pas rédigés par d’autres membres du groupe.','Post-specific and category-specific permissions for creation and editing.'=>'Permissions de création et de modification spécifiques à une publication ou à une catégorie.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'Intégration avec ACF, bbPress, BuddyPress, Relevanssi, WPML et d’autres extensions ; prise en charge améliorée de multisites.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'Afficher un texte de présentation pour les publications illisibles au lieu de les masquer dans l’interface publique.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'Restreindre les demandes directes de fichiers en fonction de l’accès de l’utilisateur/utilisatriceà la page à laquelle le fichier est attaché.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'Les personnalisations d’accès sont limitées dans le temps en retardant ou en expirant l’adhésion à un groupe de droits.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'Création automatique d’une page pour chaque utilisateur/utilisatrice dont le rôle est spécifié. Compatible avec plusieurs extensions équipe/personnel.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'Les cercles de visibilité et les cercles éditoriaux bloquent l’accès aux contenus qui ne sont pas rédigés par d’autres membres du groupe. Tout rôle WP, groupe BuddyPress ou groupe personnalisé peut être marqué comme cercle pour les types de publication spécifiés.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'Prise en charge des droits spécifiques au contenu pour la modification, l’assignation de termes et la sélection de la page parente. En combinaison avec d’autres modules, prend en charge les états de flux de travail, PublishPress et PublishPress Revisions.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'Ajoute la compatibilité ou l’intégration avec ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, et divers autres extensions. Configurer n’importe quel groupe BuddyPress comme groupe de droits. Pour les multisites, fournit des groupes de droits à l’échelle du réseau.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'Remplacer le contenu non lisible par du texte indicatif dans l’interface publique. Peut être activé pour n’importe quel type de publication. Des filtres personnalisés sont fournis, mais aucune programmation n’est nécessaire pour une utilisation de base.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'Filtrer l’accès direct aux fichiers, en fonction de l’accès de l’utilisateur/utilisatrice au(x) publication(s) à laquelle (auxquelles) le fichier est attaché. Aucune configuration supplémentaire n’est requise. Créer/modifier le fichier .htaccess dans le dossier téléversement (et dans le dossier principal pour le multisite).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'Permet de limiter la durée d’adhésion à un groupe de droits (retarder et/ou planifier l’expiration). Une interface simple de sélection de dates accompagne la sélection de l’adhésion à un groupe.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'Créer ou synchroniser des publications en fonction des utilisateurs/utilisatrices. Conçu pour les extensions équipe/personnel, mais avec un large potentiel d’utilisation.','If you like %s, please leave us a %s rating. Thank you!'=>'Si vous appréciez %s, veuillez nous laisser une note de %s. Merci !','About PublishPress Permissions'=>'À propos de PublishPress Permissions','About'=>'À propos','Permissions Documentation'=>'Documentation sur les droits','Documentation'=>'Documentation','Contact the PublishPress team'=>'Contacter l’équipe PublishPress','Contact'=>'Contact','Permission Group'=>'Groupe de droits','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'Droits spécifiques : les restrictions (« Bloqué ») ont la priorité sur les ajouts (« Activé »)','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'Droits spécifiques : aucune restriction (`Bloqué`) ne peut être appliquée aux groupes personnalisés','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'Attribution de rôles supplémentaires disponible pour les métagroupes {All} et {Anonymous}','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'Permettre aux métagroupes {All} et {Anonymous} d’obtenir des droits de lecture spécifiques pour le contenu privé','Users who have specific editing permissions for a post or attachment can also delete it'=>'Les utilisateurs/utilisatrices qui disposent de droits de modification spécifiques pour une publication ou un fichier joint peuvent également les retirer','Users who have custom editing permissions for an attachment can also delete it'=>'Les utilisateurs/utilisatrices qui disposent de droits de modification personnalisés pour un fichier joint peuvent également le retirer','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'Désactiver le filtrage de l’interface publique si l’utilisateur/utilisatrice connecté est un administrateur ou une administratrice de contenu (normalement le filtre pour forcer l’inclusion des publications privées lisibles dans le listing get_pages(), le nombre de publications, etc.','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'Désactiver le filtrage de l’interface publique pour tous les utilisateurs/utilisatrices (sous réserve de la limitation par PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'Liste de types de publication séparés par des virgules pour limiter l’effet de PP_UNFILTERED_FRONT et de apply_filters(’presspermit_skip_cap_filtering’)','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'Droits spécifiques : les ajouts (’Activé’) ne sont pas appliqués, ne peuvent pas être assignés','Don\'t assign or apply specific permissions for the \'post\' type'=>'Ne pas assigner ou appliquer des droits spécifiques pour le type « publication »','Don\'t assign or apply specific permissions for the \'page\' type'=>'Ne pas assigner ou appliquer des droits spécifiques pour le type « page »','Don\'t assign or apply specific permissions for the \'media\' type'=>'Ne pas assigner ou appliquer des droits spécifiques pour le type « média »','Don\'t assign or apply specific permissions for the specified custom post type'=>'Ne pas assigner ou appliquer des droits spécifiques pour le type de publication personnalisé spécifié','Include scheduled posts in the posts query if user can edit them'=>'Inclure les publications programmées dans la requête des publications si l’utilisateur/utilisatrice peut les modifier','Don\'t filter term post counts in get_terms() call'=>'Ne pas filtrer le nombre de publications de termes dans l’appel get_terms()','Leave unreadable posts on WP Navigation Menus'=>'Laisser les publications illisibles sur les menus de navigation de WP','Don\'t apply CSS to hide empty Nav Menus'=>'Ne pas appliquer CSS pour masquer les menus de navigation vides','For legacy Nav Menus, hide empty nav menu div'=>'Pour les anciens menus de navigation, masquer la div vide du menu de navigation','Leave terms with no readable posts on WP Navigation Menus'=>'Laisser les termes sans publications lisibles sur les menus de navigation de WP','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'Lorsque la présentation est appliquée avec l’option de redirection activée, l’url originale est ajoutée à l’argument « redirect_to »','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'Pour la compatibilité avec la présentation, spécifier un argument de redirection à utiliser à la place de redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'Pour la compatibilité avec la présentation, spécifier un argument de redirection supplémentaire différent de redirect_to','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'Pour la compatibilité avec la présentation, empêcher l’argument pp_permissions d’être ajouté aux redirections','Filter priority for \'get_pages\' filter (default: 1)'=>'Filtre prioritaire pour le filtre `get_pages` (par défaut : 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'N’inclure pas les pages privées lisibles dans le widget Pages ou d’autres résultats de `wp_list_pages()`/`get_pages()`    ','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'Si certaines pages ont été supprimées des résultats de `get_pages()`, modifiez les valeurs `post_parent` correspondantes des pages enfant vers un ancêtre visible','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'Ne modifier jamais la valeur post_parent dans le jeu de résultats get_pages(), même si certaines pages ont été supprimées','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'Pour des raisons de performances, modifiez la requête de la base de données get_pages() pour ne renvoyer qu’un sous-ensemble de champs, en excluant post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'Ne pas appliquer la présentation du contenu aux résultats de get_pages() (laissez les publications illisibles cachées)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'Si certains termes ont été supprimés des résultats de `get_terms()`, modifiez les valeurs parentales correspondantes des termes enfants vers un ancêtre visible','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'Ne modifier jamais la valeur du parent dans le jeu de résultats get_terms(), même si certains termes ont été retirés','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'Définir l’auteur à l’utilisateur/utilisatrice actuel si la permission autoset_post_author / autoset_page_author est attribuée','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'Laisser la médiathèque avec des critères d’accès normaux basés sur les permissions du rôle de l’utilisateur/utilisatrice ou de l’utilisatrice ','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'Accommoder les solutions de téléversement de l’interface publique qui requièrent des permissions de modification de la page pour la demande de téléversement asynchrone','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'Traiter les médias attachés à des types de publication non enregistrés comme des médias non attachés, afin d’éviter un filtrage inapproprié et déroutant','Attached Files Private setting available'=>'Réglage privé des fichiers joints disponible','Comma-separated list of mime types to exclude from File Access filtering'=>'Liste de types de MIME séparés par des virgules à exclure du filtrage de l’accès aux fichiers','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'Liste séparée par des virgules des types de MIME à inclure dans le filtrage de l’accès aux fichiers (en contournant les autres)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'Lorsque l’accès aux fichiers est bloqué, ne pas définir la propriété WP_Query 404 / 403','HTTP status code to send when file access is blocked'=>'Code d’état HTTP à envoyer lorsque l’accès au fichier est bloqué','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'Dans la liste des comptes, les groupes de droits dans la colonne personnalisée sont des liens de filtre de liste au lieu de liens de modification de groupe','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'Débloquer Droits > Réglages > Coeur > Interface d’administration > « Masquer les publications non modifiables »','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'Dans le script async-upload.php, filtrer la récupération par l’auteur/autrice de la pièce jointe qu’il vient de télécharger','Don\'t filter comment display or moderation within wp-admin'=>'Ne pas filtrer l’affichage ou la modération des commentaires dans wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'Permettre aux administrateurs/administratrices d’apparaître dans les groupes de droits, même en n’étant pas soumis à des restrictions','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'Si vous assignez des droits de propagation à une branche de page, ils écrasent les droits explicitement assignés dans les sous-pages','Max number of specific permissions to insert in a single database query (default 1000)'=>'Nombre maximum de droits spécifiques à insérer dans une seule requête de base de données (par défaut 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'Ne modifiez pas les index du menu d’administration pour placer le menu « Droits » sous « Comptes »','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'Ne ajoutez pas un menu de droits. À la place, ajoutez des éléments de menu dans les menus Utilisateurs/utilisatrices et Réglages.','Customize Permissions screen title for Groups'=>'Personnaliser la titre de l’écran « Droits » pour les groupes','Customize Permission Groups caption on user profile'=>'Personnaliser la légende des groupes de droits dans le profil du compte','Only one group is selectable on Add User screen'=>'Un seul groupe peut être sélectionné sur l’écran « Ajouter un compte »','Only one group is selectable on Edit User screen'=>'Un seul groupe peut être sélectionné sur l’écran « Modifier le compte »','Display a custom hint on Permissions > User Groups'=>'Afficher un conseil personnalisé dans « Droits » > « Groupes d’utilisateurs/utilisatrices »','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'Nombre maximal de publications/termes non-hiérarchiques à afficher en même temps (par page)','Max number of hierarchical posts / terms to display at one time (per page)'=>'Nombre maximal de publications/termes hiérarchiques à afficher en même temps (par page)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'Désactiver l’auto-détermination du nombre de niveaux de l’arbre de page à rendre visible par défaut. A la place, utilisez la valeur spécifiée.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'Nombre cible de pages/termes visibles, utilisé pour l’autodétermination du nombre de niveaux visibles','Make search function on the post selection metabox look at post content'=>'Faire en sorte que la fonction de recherche de la boîte méta de sélection des publications affiche le contenu de la publication','Make search function on the post selection metabox look at post excerpt'=>'Faire en sorte que la fonction de recherche de la boîte méta de sélection des publications affiche l’extrait de la publication','Search by last name instead of display name'=>'Recherche par nom de famille au lieu du nom affiché','User field to search by default'=>'Champ utilisateur/utilisatrice à rechercher par défaut','User meta fields selectable for search (comma-separated)'=>'Champs méta de l’utilisateur/utilisatrice sélectionnables pour la recherche (séparés par des virgules)','User meta fields which should be treated as numeric (comma-separated)'=>'Champs méta de l’utilisateur/utilisatrice qui doivent être traités comme des numériques (séparés par des virgules)','User meta fields which should be treated as boolean (comma-separated)'=>'Champs méta de l’utilisateur/utilisatrice qui doivent être traités comme des booléens (séparés par des virgules)','Use display name for search results instead of user_login'=>'Utiliser le nom affiché pour les résultats de recherche au lieu de user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'Lors de la synchronisation des métagroupes de rôles avec les rôles WP actuellement définis, ne supprimez pas les groupes pour les rôles WP précédemment définis.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'Détection forcée des rôles d’utilisateur/utilisatrice WP qui sont ajoutés dynamiquement mais non stockés dans la base de données WP.','To save memory on front end access, don\'t register any filters related to content editing'=>'Pour économiser de la mémoire sur l’accès à l’interface publique, ne enregistrez pas de filtres liés à la modification du contenu','Attached media do not have any comments, so don\'t append clauses to comment queries for them'=>'Les médias attachés n’ont pas de commentaires, donc n’ajoutez pas de clauses aux requêtes de commentaires pour eux','Reduce overhead of pages query (in get_pages() and wp-admin) by defaulting fields to a set list that does not include post_content '=>'Réduire la surcharge de la requête pages (in get_pages() et wp-admin) en utilisant par défaut une liste de champs qui n’inclut pas post_content ','Reduce overhead of wp-admin posts query by defaulting fields to a set list that does not include post_content '=>'Réduire la surcharge de la requête publication de wp-admin en utilisant par défaut une liste de champs qui n’inclut pas post_content ','Reduce overhead of wp-admin Media query by defaulting fields to a set list that does not include post_content '=>'Réduire la surcharge de la requête Media de wp-admin en utilisant par défaut une liste de champs qui n’inclut pas post_content ','Reduce overhead of wp-admin query for specified custom post type by defaulting fields to a set list that does not include post_content '=>'Réduire la surcharge de la requête wp-admin pour un type de publication personnalisé spécifié en définissant par défaut les champs dans une liste qui n’inclut pas post_content ','Work around database setup warnings (at plugin activation) on some servers'=>'Contournement des avertissements de configuration de la base de données (à l’activation de l’extension) sur certains serveurs','Development use only (suppresses post_status = \'publish\' clause for unfiltered post types with anonymous user)'=>'Utilisation en développement uniquement (supprime la clause `post_status = `publish`` pour les types de publications non filtrées avec un utilisateur/utilisatrice anonyme)','Development use only (on front end, do not replace \'post_status = \'publish\'\' clause with filtered equivalent)'=>'Utilisation en développement uniquement